/**
 * Argument tuples of every imgproxy video option, by canonical name.
 * `/rs:fill:300:400/` is `{ resize: ["fill", 300, 400] }`: `null` is an empty
 * argument, booleans are written `1`/`0`.
 */
export interface ImgproxyVideoArgs {
  /**
   * Audio bit rate (8k..512k; ignored by flac and wav). URL: `audio_bitrate`, `ab`; arguments bit/s (k); default codec default.
   *
   * URL names: `audio_bitrate`, `ab`.
   * milestone M5 (WP-123); scope request.
   * @example ["128k"]
   */
  "audio_bitrate":
    | [bitrate: string];
  /**
   * Downmix to mono or stereo. URL: `audio_channels`, `ach`; arguments 1 or 2; default source.
   *
   * URL names: `audio_channels`, `ach`.
   * milestone M5 (WP-123); scope request.
   * @example [1]
   */
  "audio_channels":
    | [channels: number];
  /**
   * Audio codec (must suit the container). URL: `audio_codec`, `ac`; arguments auto, aac, opus, mp3, flac, pcm; default auto.
   *
   * URL names: `audio_codec`, `ac`.
   * milestone M5 (WP-122); scope request.
   * @example ["aac"]
   */
  "audio_codec":
    | [codec: "aac" | "auto" | "flac" | "mp3" | "opus" | "pcm"];
  /**
   * Colour of the bars of extend. URL: `background`, `bg`; arguments hex; default 000000.
   *
   * URL names: `background`, `bg`.
   * milestone M5 (WP-122); scope request.
   * @example ["ffffff"]
   */
  "background":
    | [color: string | null];
  /**
   * Skip the result cache (XI_CACHE_ALLOW_BYPASS). URL: `bypass_cache`, `bc`; arguments bool; default false.
   *
   * URL names: `bypass_cache`, `bc`.
   * milestone M2 (WP-52); scope request; imgproxy Pro option (free here).
   * @example [true]
   */
  "bypass_cache":
    | [bypass: boolean | null];
  /**
   * Tags for the Cache-Tag response header. URL: `cache_tags`, `ct`; arguments tags… (visible ASCII, no commas; replaces earlier tags); default —.
   *
   * URL names: `cache_tags`, `ct`.
   * milestone M2 (WP-34b, WP-64 end-to-end test); scope request; imgproxy Pro option (free here).
   * @example ["product","hero"]
   */
  "cache_tags":
    | [tag: string | null, ...tags: Array<string | null>];
  /**
   * Changes the URL, the cache key and the ETag. URL: `cachebuster`, `cb`; arguments string; default —.
   *
   * URL names: `cachebuster`, `cb`.
   * milestone M1; scope request.
   * @example ["v2"]
   */
  "cachebuster":
    | [value: string | null];
  /**
   * Constant rate factor (wins over quality). URL: `crf`; arguments 0..63; default 0.
   *
   * URL names: `crf`.
   * milestone M5 (WP-122); scope request.
   * @example [30]
   */
  "crf":
    | [crf: number];
  /**
   * Crop a rectangle (pixels) of the rotated frame before the resize. URL: `crop`, `c`; arguments w:h:gravity; default —.
   *
   * URL names: `crop`, `c`.
   * milestone M5 (WP-122); scope request.
   * @example [640,360,"nowe"]
   */
  "crop":
    | [width: number, height?: number | null, type?: "ce" | "no" | "so" | "ea" | "we" | "noea" | "nowe" | "soea" | "sowe" | null, x_offset?: number | null, y_offset?: number | null];
  /**
   * Length of the output from start (exclusive with end). URL: `duration`, `vd`; arguments seconds; default to the end.
   *
   * URL names: `duration`, `vd`.
   * milestone M5 (WP-122); scope request.
   * @example [3]
   */
  "duration":
    | [seconds: number];
  /**
   * End the output at this time of the source (exclusive with duration). URL: `end`, `ve`; arguments seconds; default end of the source.
   *
   * URL names: `end`, `ve`.
   * milestone M5 (WP-122); scope request.
   * @example [4]
   */
  "end":
    | [seconds: number];
  /**
   * Let fit enlarge a smaller source. URL: `enlarge`, `el`; arguments bool; default false.
   *
   * URL names: `enlarge`, `el`.
   * milestone M5 (WP-122); scope request.
   * @example [true]
   */
  "enlarge":
    | [enlarge: boolean | null];
  /**
   * URL expiry (404 afterwards). URL: `expires`, `exp`; arguments unix ts; default —.
   *
   * URL names: `expires`, `exp`.
   * milestone M1; scope request.
   * @example [4102444800]
   */
  "expires":
    | [timestamp: number];
  /**
   * Pad a fit to the whole box with the background colour. URL: `extend`, `ex`; arguments bool; default false.
   *
   * URL names: `extend`, `ex`.
   * milestone M5 (WP-122); scope request.
   * @example [true]
   */
  "extend":
    | [extend: boolean | null];
  /**
   * Fade in from black and silence, and out to them (seconds). URL: `fade`, `fd`; arguments in:out; default 0:0.
   *
   * URL names: `fade`, `fd`.
   * milestone M5 (WP-123); scope request.
   * @example [1,2]
   */
  "fade":
    | [in_: number | null, out?: number | null];
  /**
   * Content-Disposition file name. URL: `filename`, `fn`; arguments name:encoded; default source basename.
   *
   * URL names: `filename`, `fn`.
   * milestone M1; scope request.
   * @example ["photo"]
   */
  "filename":
    | [name: string | null, encoded?: boolean | null];
  /**
   * Mirror after the rotation. URL: `flip`, `fl`; arguments h:v; default false:false.
   *
   * URL names: `flip`, `fl`.
   * milestone M5 (WP-122); scope request.
   * @example [true,false]
   */
  "flip":
    | [horizontal: boolean | null, vertical?: boolean | null];
  /**
   * Output container (the source extension sets it too); png and webp are waveform pictures, m3u8 and mpd streams (WP-126). URL: `format`, `f`, `ext`; arguments mp4, webm, m4a, mp3, opus, ogg, flac, wav, png, webp, m3u8, mpd; default mp4.
   *
   * URL names: `format`, `f`, `ext`.
   * milestone M5 (WP-122); scope request.
   * @example ["webm"]
   */
  "format":
    | [format: "mp4" | "webm" | "m4a" | "mp3" | "opus" | "ogg" | "flac" | "wav" | "png" | "webp" | "m3u8" | "mpd"];
  /**
   * Output frame rate (capped by XI_VIDEO_TRANSFORM_MAX_FPS). URL: `fps`; arguments rate; default source.
   *
   * URL names: `fps`.
   * milestone M5 (WP-122); scope request.
   * @example [24]
   */
  "fps":
    | [fps: number];
  /**
   * Anchor of fill crops, pads and crops (a compass point; the pixel offsets move crops). URL: `gravity`, `g`; arguments type:x:y; default ce:0:0.
   *
   * URL names: `gravity`, `g`.
   * milestone M5 (WP-122); scope request.
   * @example ["soea",10,10]
   */
  "gravity":
    | [type: "ce" | "no" | "so" | "ea" | "we" | "noea" | "nowe" | "soea" | "sowe", x_offset?: number | null, y_offset?: number | null];
  /**
   * Check the source bytes against a digest. URL: `hashsum`, `hs`; arguments none, or md5/sha1/sha256/sha512:hex; default none.
   *
   * URL names: `hashsum`, `hs`.
   * milestone M2 (WP-64); scope request; imgproxy Pro option (free here).
   * @example ["sha256","e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"]
   */
  "hashsum":
    | [type: "none" | "md5" | "sha1" | "sha256" | "sha512" | null, hashsum?: string | null];
  /**
   * Output height (rounded down to even). URL: `height`, `h`; arguments px; default 0.
   *
   * URL names: `height`, `h`.
   * milestone M5 (WP-122); scope request.
   * @example [360]
   */
  "height":
    | [height: number];
  /**
   * Time between keyframes (GOP length, 0.1..60 s). URL: `keyframe_interval`, `ki`; arguments seconds; default 2.
   *
   * URL names: `keyframe_interval`, `ki`.
   * milestone M5 (WP-122); scope request.
   * @example [1]
   */
  "keyframe_interval":
    | [seconds: number];
  /**
   * EBU R128 loudness normalisation (single-pass loudnorm). URL: `loudnorm`, `ln`; arguments enabled:I:TP:LRA; default false:-23:-1:7.
   *
   * URL names: `loudnorm`, `ln`.
   * milestone M5 (WP-123); scope request.
   * @example [true,-16,-1.5,11]
   */
  "loudnorm":
    | [enabled: boolean | null, integrated?: number | null, true_peak?: number | null, range?: number | null];
  /**
   * Drop the audio stream. URL: `mute`, `mu`; arguments bool; default false.
   *
   * URL names: `mute`, `mu`.
   * milestone M5 (WP-123); scope request.
   * @example [true]
   */
  "mute":
    | [mute: boolean | null];
  /**
   * Fade the watermark overlay in and out (seconds, within its window). URL: `overlay_fade`, `of`; arguments in:out; default 0:0.
   *
   * URL names: `overlay_fade`, `of`.
   * milestone M5 (WP-124); scope request.
   * @example [0.5,0.5]
   */
  "overlay_fade":
    | [in_: number | null, out?: number | null];
  /**
   * Show the watermark overlay (wm, wmu, wmt) from start to end seconds of the output. URL: `overlay_window`, `ow`; arguments start:end; default 0:0.
   *
   * URL names: `overlay_window`, `ow`.
   * milestone M5 (WP-124); scope request.
   * @example [1,4]
   */
  "overlay_window":
    | [start: number | null, end?: number | null];
  /**
   * Expand video presets (XI_VIDEO_TRANSFORM_PRESETS) in place. URL: `preset`, `pr`; arguments names…; default —.
   *
   * URL names: `preset`, `pr`.
   * milestone M5 (WP-132); scope request.
   * @example ["web"]
   */
  "preset":
    | [name: string, ...names: Array<string>];
  /**
   * Video quality, mapped onto the codec's CRF scale. URL: `quality`, `q`; arguments 1..100; default 0.
   *
   * URL names: `quality`, `q`.
   * milestone M5 (WP-122); scope request.
   * @example [70]
   */
  "quality":
    | [quality: number];
  /**
   * Stream the source without processing. URL: `raw`; arguments bool; default false.
   *
   * URL names: `raw`.
   * milestone M1; scope request.
   * @example [true]
   */
  "raw":
    | [raw: boolean | null];
  /**
   * Resize like imgproxy: fit (scale-down, or contain with enlarge; extend pads), fill and fill-down (cover, cropped by gravity), force (stretch). URL: `resize`, `rs`; arguments type:w:h:enlarge:extend; default fit:0:0:false:false.
   *
   * URL names: `resize`, `rs`.
   * milestone M5 (WP-122); scope request.
   * @example ["fill",640,360]
   */
  "resize":
    | [type: "fit" | "fill" | "fill-down" | "force" | null, width?: number | null, height?: number | null, enlarge?: boolean | null, extend?: boolean | null];
  /**
   * Resizing type (auto is not available for video). URL: `resizing_type`, `rt`; arguments fit, fill, fill-down, force; default fit.
   *
   * URL names: `resizing_type`, `rt`.
   * milestone M5 (WP-122); scope request.
   * @example ["fill"]
   */
  "resizing_type":
    | [type: "fit" | "fill" | "fill-down" | "force"];
  /**
   * Download instead of inline display. URL: `return_attachment`, `att`; arguments bool; default config.
   *
   * URL names: `return_attachment`, `att`.
   * milestone M1; scope request.
   * @example [true]
   */
  "return_attachment":
    | [attachment: boolean | null];
  /**
   * Rotate clockwise after the display matrix. URL: `rotate`, `rot`; arguments multiple of 90; default 0.
   *
   * URL names: `rotate`, `rot`.
   * milestone M5 (WP-122); scope request.
   * @example [90]
   */
  "rotate":
    | [angle: number];
  /**
   * Output sample rate (the codec must support it: Opus 8/12/16/24/48 kHz). URL: `sample_rate`, `sr`; arguments Hz; default source.
   *
   * URL names: `sample_rate`, `sr`.
   * milestone M5 (WP-123); scope request.
   * @example [44100]
   */
  "sample_rate":
    | [hz: number];
  /**
   * Length of a stream's segments (1..30 s). URL: `segment_duration`, `sgd`; arguments seconds; default XI_VIDEO_TRANSFORM_SEGMENT_DURATION (6).
   *
   * URL names: `segment_duration`, `sgd`.
   * milestone M5 (WP-126); scope request.
   * @example [4]
   */
  "segment_duration":
    | [seconds: number];
  /**
   * Container of a stream's segments: fmp4 (CMAF, HLS 7 and DASH) or ts (MPEG-TS for older HLS players: HLS only, H.264 and AAC muxed in each segment; images with libx264 only). URL: `segment_format`, `sgf`; arguments format; default fmp4.
   *
   * URL names: `segment_format`, `sgf`.
   * milestone M5 (WP-131); scope request.
   * @example ["ts"]
   */
  "segment_format":
    | [format: "cmaf" | "fmp4" | "mpegts" | "ts"];
  /**
   * Resize without the type. URL: `size`, `s`; arguments w:h:enlarge:extend; default 0:0:false:false.
   *
   * URL names: `size`, `s`.
   * milestone M5 (WP-122); scope request.
   * @example [640,360,false,true]
   */
  "size":
    | [width: number | null, height?: number | null, enlarge?: boolean | null, extend?: boolean | null];
  /**
   * Start the output at this time of the source (exact, from the keyframe before it). URL: `start`, `vs`; arguments seconds; default 0.
   *
   * URL names: `start`, `vs`.
   * milestone M5 (WP-122); scope request.
   * @example [1.5]
   */
  "start":
    | [seconds: number];
  /**
   * Deliver an HLS or DASH stream (as the m3u8 or mpd extension does) with these renditions (at most 8; none: the configured ladder). Rungs above the source are dropped. URL: `stream`, `st`; arguments protocol:height…; default none (a file).
   *
   * URL names: `stream`, `st`.
   * milestone M5 (WP-126); scope request.
   * @example ["hls",360,720]
   */
  "stream":
    | [protocol: "dash" | "hls", ...heights: Array<number | null>];
  /**
   * Draw the output's running time (FFmpeg drawtext with a fixed expansion). URL: `timecode`, `tc`; arguments format:position:x:y:size:color:opacity; default none:sowe:0:0:0:ffffff:1.
   *
   * URL names: `timecode`, `tc`.
   * milestone M5 (WP-124); scope request.
   * @example ["hms","sowe",8,8,20]
   */
  "timecode":
    | [format: "hms" | "seconds" | "none", position?: "ce" | "no" | "so" | "ea" | "we" | "noea" | "nowe" | "soea" | "sowe" | null, x_offset?: number | null, y_offset?: number | null, size?: number | null, color?: string | null, opacity?: number | null];
  /**
   * Cap the video bit rate (50k..200M). URL: `video_bitrate`, `vb`; arguments bit/s (k, M); default uncapped.
   *
   * URL names: `video_bitrate`, `vb`.
   * milestone M5 (WP-122); scope request.
   * @example ["2M"]
   */
  "video_bitrate":
    | [bitrate: string];
  /**
   * Video codec (h264 and hevc need the gpl image). URL: `video_codec`, `vc`; arguments auto, h264, av1, vp9, hevc; default auto.
   *
   * URL names: `video_codec`, `vc`.
   * milestone M5 (WP-122); scope request.
   * @example ["av1"]
   */
  "video_codec":
    | [codec: "auto" | "av1" | "h264" | "h265" | "hevc" | "vp9"];
  /**
   * Change the audio level (-60 dB..+20 dB). URL: `volume`, `vol`; arguments factor or NdB; default 1.
   *
   * URL names: `volume`, `vol`.
   * milestone M5 (WP-123); scope request.
   * @example ["-6dB"]
   */
  "volume":
    | [gain: string];
  /**
   * Draw the watermark. URL: `watermark`, `wm`; arguments opacity:pos:x:y:scale; pos incl. `re` (tile), `ch` (chessboard, Pro); default off.
   *
   * URL names: `watermark`, `wm`.
   * milestone M1 (`re` M1, `ch` M3 WP-77); scope pipeline.
   * @example [0.5,"soea",10,10,0.2]
   */
  "watermark":
    | [opacity: number, position?: "ce" | "no" | "so" | "ea" | "we" | "noea" | "nowe" | "soea" | "sowe" | "re" | "ch" | null, x_offset?: number | null, y_offset?: number | null, scale?: number | null];
  /**
   * Watermark rotation, clockwise. URL: `watermark_rotate`, `wm_rot`, `wmr`; arguments degrees; default 0.
   *
   * URL names: `watermark_rotate`, `wm_rot`, `wmr`.
   * milestone M3 (WP-77); scope pipeline; imgproxy Pro option (free here).
   * @example [45]
   */
  "watermark_rotate":
    | [angle: number];
  /**
   * Watermark shadow: its alpha blurred with sigma, in black. URL: `watermark_shadow`, `wmsh`; arguments sigma; default off.
   *
   * URL names: `watermark_shadow`, `wmsh`.
   * milestone M3 (WP-77); scope pipeline; imgproxy Pro option (free here).
   * @example [2]
   */
  "watermark_shadow":
    | [sigma: number];
  /**
   * Watermark size in pixels (fit, enlarging; used when the wm scale is 0). URL: `watermark_size`, `wms`; arguments w:h; default 0:0.
   *
   * URL names: `watermark_size`, `wms`.
   * milestone M3 (WP-77); scope pipeline; imgproxy Pro option (free here).
   * @example [100,0]
   */
  "watermark_size":
    | [width: number | null, height?: number | null];
  /**
   * Text watermark (replaces watermark_url); markup is sanitised to a whitelist, font `sans 16` by default. URL: `watermark_text`, `wmt`; arguments base64url Pango markup; default —.
   *
   * URL names: `watermark_text`, `wmt`.
   * milestone M3 (WP-78); scope pipeline; imgproxy Pro option (free here).
   * @example ["SGVsbG8"]
   */
  "watermark_text":
    | [text: string | null];
  /**
   * Watermark image source, fetched like a source (allowlist, SSRF policy, byte limit, origin cache). URL: `watermark_url`, `wmu`; arguments base64url URL; default config image.
   *
   * URL names: `watermark_url`, `wmu`.
   * milestone M3 (WP-77); scope pipeline; imgproxy Pro option (free here).
   * @example ["aHR0cHM6Ly9leGFtcGxlLmNvbS93LnBuZw"]
   */
  "watermark_url":
    | [url: string | null];
  /**
   * Render the audio as a width × height (default 1024×256) PNG or WebP picture. URL: `waveform`, `wf`; arguments enabled:color:background:split; default false:000000::false.
   *
   * URL names: `waveform`, `wf`.
   * milestone M5 (WP-123); scope request.
   * @example [true,"2266cc","ffffff",false]
   */
  "waveform":
    | [enabled: boolean | null, color?: string | null, background?: string | null, split_channels?: boolean | null];
  /**
   * Output width (rounded down to even). URL: `width`, `w`; arguments px; default 0.
   *
   * URL names: `width`, `w`.
   * milestone M5 (WP-122); scope request.
   * @example [640]
   */
  "width":
    | [width: number];
}

